package raft

const (
	minElectionTimeout  = 10
	electionTimeoutSpan = 10
)

// Node is an election-only, pure educational Raft node.
type Node struct {
	id              uint64
	peers           []uint64
	rand            Rand
	role            Role
	term            uint64
	votedFor        uint64
	log             []Entry
	votes           []uint64
	electionElapsed int
	electionTimeout int
}

// NewNode creates a follower from durable state.
func NewNode(config Config) *Node {
	if config.ID == 0 {
		panic("raft node ID must be non-zero")
	}
	if config.Rand == nil {
		panic("raft node requires a deterministic Rand")
	}
	node := &Node{
		id:       config.ID,
		peers:    orderedPeers(config.ID, config.Peers),
		rand:     config.Rand,
		role:     Follower,
		term:     config.Persistent.Term,
		votedFor: config.Persistent.VotedFor,
		log:      append([]Entry(nil), config.Persistent.Log...),
	}
	node.resetElectionTimeout()
	return node
}

// Tick advances one virtual timer tick.
func (n *Node) Tick() Output {
	if n.role == Leader {
		return n.heartbeats()
	}
	n.electionElapsed++
	if n.electionElapsed < n.electionTimeout {
		return Output{}
	}
	return n.startElection()
}

// Step handles one election-only protocol message.
func (n *Node) Step(message Message) Output {
	if message.To != 0 && message.To != n.id {
		return Output{}
	}

	output := Output{}
	if message.Term > n.term {
		n.becomeFollower(message.Term)
		output.Persist = n.persistent()
	}

	switch message.Type {
	case RequestVote:
		return n.handleRequestVote(message, output)
	case RequestVoteResp:
		return n.handleRequestVoteResp(message, output)
	case Heartbeat:
		return n.handleHeartbeat(message, output)
	case HeartbeatResp:
		return output
	default:
		return output
	}
}

// State returns a copy suitable for deterministic simulation inspection.
func (n *Node) State() State {
	return State{
		ID:       n.id,
		Role:     n.role,
		Term:     n.term,
		VotedFor: n.votedFor,
		Log:      append([]Entry(nil), n.log...),
	}
}

func (n *Node) startElection() Output {
	n.role = Candidate
	n.term++
	n.votedFor = n.id
	n.votes = []uint64{n.id}
	n.resetElectionTimeout()

	lastIndex, lastTerm := n.lastLog()
	output := Output{Persist: n.persistent()}
	for _, peer := range n.peers {
		output.Msgs = append(output.Msgs, Message{
			Type:         RequestVote,
			From:         n.id,
			To:           peer,
			Term:         n.term,
			LastLogIndex: lastIndex,
			LastLogTerm:  lastTerm,
		})
	}
	return output
}

func (n *Node) handleRequestVote(message Message, output Output) Output {
	granted := false
	if message.Term == n.term && (n.votedFor == 0 || n.votedFor == message.From) && n.candidateUpToDate(message) {
		granted = true
		if n.votedFor != message.From {
			n.votedFor = message.From
			n.resetElectionTimeout()
			output.Persist = n.persistent()
		}
	}
	output.Msgs = append(output.Msgs, Message{
		Type:        RequestVoteResp,
		From:        n.id,
		To:          message.From,
		Term:        n.term,
		VoteGranted: granted,
	})
	return output
}

func (n *Node) handleRequestVoteResp(message Message, output Output) Output {
	if message.Term != n.term || n.role != Candidate || !message.VoteGranted {
		return output
	}
	if !contains(n.votes, message.From) {
		n.votes = append(n.votes, message.From)
	}
	if len(n.votes) >= n.majority() {
		n.role = Leader
		n.electionElapsed = 0
		return n.heartbeats()
	}
	return output
}

func (n *Node) handleHeartbeat(message Message, output Output) Output {
	if message.Term < n.term {
		return output
	}
	if message.Term == n.term && n.role != Follower {
		n.role = Follower
		n.votes = nil
	}
	n.electionElapsed = 0
	output.Msgs = append(output.Msgs, Message{
		Type: HeartbeatResp,
		From: n.id,
		To:   message.From,
		Term: n.term,
	})
	return output
}

func (n *Node) heartbeats() Output {
	output := Output{}
	for _, peer := range n.peers {
		output.Msgs = append(output.Msgs, Message{
			Type: Heartbeat,
			From: n.id,
			To:   peer,
			Term: n.term,
		})
	}
	return output
}

func (n *Node) becomeFollower(term uint64) {
	n.role = Follower
	n.term = term
	n.votedFor = 0
	n.votes = nil
	n.resetElectionTimeout()
}

func (n *Node) candidateUpToDate(message Message) bool {
	if !useLogFreshness() {
		return true
	}
	lastIndex, lastTerm := n.lastLog()
	if message.LastLogTerm != lastTerm {
		return message.LastLogTerm > lastTerm
	}
	return message.LastLogIndex >= lastIndex
}

func (n *Node) persistent() *Persistent {
	persistent := Persistent{
		Term:     n.term,
		VotedFor: n.votedFor,
		Log:      append([]Entry(nil), n.log...),
	}
	if !includeVoteInPersist() {
		persistent.VotedFor = 0
	}
	return &persistent
}

func (n *Node) resetElectionTimeout() {
	draw := n.rand.Intn(electionTimeoutSpan)
	if draw < 0 || draw >= electionTimeoutSpan {
		panic("raft Rand returned value outside Intn range")
	}
	n.electionElapsed = 0
	n.electionTimeout = minElectionTimeout + draw
}

func (n *Node) lastLog() (uint64, uint64) {
	if len(n.log) == 0 {
		return 0, 0
	}
	last := n.log[len(n.log)-1]
	return last.Index, last.Term
}

func (n *Node) majority() int {
	return (len(n.peers)+1)/2 + 1
}

func contains(values []uint64, value uint64) bool {
	for _, candidate := range values {
		if candidate == value {
			return true
		}
	}
	return false
}

func orderedPeers(id uint64, peers []uint64) []uint64 {
	ordered := append([]uint64(nil), peers...)
	for index := 1; index < len(ordered); index++ {
		for current := index; current > 0 && ordered[current] < ordered[current-1]; current-- {
			ordered[current], ordered[current-1] = ordered[current-1], ordered[current]
		}
	}
	unique := ordered[:0]
	for _, peer := range ordered {
		if peer != 0 && peer != id && !contains(unique, peer) {
			unique = append(unique, peer)
		}
	}
	return unique
}
